def module(mode):
    need(type(mode) is str and mode in MODULES,'only exact unchanged model convergence relay mode admitted')
    return MODULES[mode]


def source_gate(mode):
    selected=module(mode)
    need(bool(SOURCE_GATE) and STRICT_GUARD_COUNT>3370,'actual three-file relay source gate and exact denominator not frozen')
    gate=document(SOURCE_GATE)
    need(gate['status']=='passed_source_only' and gate['findings']==[]
        and gate['candidate_pins']==CORE_PINS and gate['reviewed_modules']==MODULES
        and gate['candidate_compiled'] is False and gate['actual_new_qualified_queries']==0
        and all(gate[k] is False for k in AUTHORITY),'exact three-file one-mode independent relay source gate required')
    for row in CORE_PINS.values():exact(row)
    need(selected['source'] in CORE_PINS.values(),'selected relay source absent from independent gate')
    need(HISTORICAL_MODEL_SOURCE in CONTEXT_PINS
        and (selected['source']['bytes'],selected['source']['sha256'])
          ==(HISTORICAL_MODEL_SOURCE['bytes'],HISTORICAL_MODEL_SOURCE['sha256']),
        'selected source must match the exact named historical model descriptor')
    need(exact(selected['source'],True)==exact(HISTORICAL_MODEL_SOURCE,True),
        'fresh relay must be byte-identical to exact historical source; no copied evidence is modern acceptance')
    return gate


def closed_scope_rows():
    rows=[]
    for selected in CLOSED_SCOPE_RECORDS:
        seal=PT['PT']['seal_census'](selected['seal'])
        need(seal['scope_root']==selected['scope_root']
            and seal['regular_file_count']==selected['regular_file_count']==len(seal['files'])
            and seal['regular_file_bytes']==selected['regular_file_bytes']==sum(r['bytes'] for r in seal['files'])
            and seal['file_inventory_sha256']==selected['file_inventory_sha256']
            and seal['fixture_symlinks']==[] and seal['seal_self_excluded_from_files'] is True
            and all(seal[k] is False for k in AUTHORITY),
            'only exact closed Tail/GeneratedRelay and unexecuted prior relay scope manifests permitted')
        need(seal['files']==sorted(seal['files'],key=lambda r:Path(r['path']))
            and len({r['path'] for r in seal['files']})==len(seal['files']),
            'closed scope file population must be unique and ordered')
        for row in seal['files']:
            need(Path(row['path']).is_relative_to(Path(selected['scope_root']))
                and row['path']!=selected['seal']['path'],'closed leaf must belong to its fixed scope')
            exact(row);rows.append(row)
        exact(selected['seal']);rows.append(selected['seal'])
    return rows


def complete_guard_union():
    need(bool(SOURCE_GATE) and STRICT_GUARD_COUNT>3370,'actual relay source gate and exact guard count not frozen')
    parent_rows,parent_inherited=PT['complete_guard_union']()
    need(len(parent_rows)==PT['STRICT_GUARD_COUNT']==3370,
         'exact complete accepted GeneratedRelay guard-context cohort required')
    inherited=document(PRIOR_REQUEST)
    need(inherited['strict_old_inputs']==parent_rows
        and inherited['strict_guard_count']==PT['STRICT_GUARD_COUNT']
        and inherited['protected_live_sources']==parent_inherited['protected_live_sources']
        and inherited['original_checkout_guards']==parent_inherited['original_checkout_guards']
        and inherited['prior_language_context_request']==PT['PRIOR_REQUEST']
        and inherited['prior_language_context_seal']==PT['PRIOR_SEAL']
        and all(inherited[k] is False for k in AUTHORITY),
        'exact freshly recomputed closed GeneratedRelay request/context joins required')
    rows={r['path']:r for r in parent_rows}
    additions=[PT_PIN,PT_TOOLING_GATE,PRIOR_REQUEST,PRIOR_SEAL,*CONTEXT_PINS,
               *CORE_PINS.values(),SOURCE_GATE,*closed_scope_rows()]
    for row in additions:
        need(row['path'] not in rows or rows[row['path']]==row,'overlapping guarded body differs')
        exact(row);rows[row['path']]=row
    need(len(rows)==STRICT_GUARD_COUNT,'exact convergence relay additive guard denominator differs')
    return [rows[p] for p in sorted(rows)],inherited


def validate_guard_union(request):
    rows,inherited=complete_guard_union()
    need(request['strict_old_inputs']==rows and request['strict_guard_count']==STRICT_GUARD_COUNT
        and request['protected_live_sources']==inherited['protected_live_sources']
        and request['original_checkout_guards']==inherited['original_checkout_guards']
        and request['prior_language_context_request']==PRIOR_REQUEST
        and request['prior_language_context_seal']==PRIOR_SEAL,
        'exact closed ancestry and convergence relay guard population required')


def qualified_module(name,profile,check_row=None):
    need(name in BASE_IMPORT_NAMES,'only exact genuinely present two local baseline imports permitted')
    selected=BASE_IMPORT_RECORDS[name]
    need(check_row is None or check_row==selected['check'],'only exact genuine baseline check descriptor allowed')
    need([r for r in profile['source_import_modules'] if r['module']==name]==[selected['source_record']]
        and [r for r in profile['local_checked_modules'] if r['module']==name]==[selected['local_record']],
        'literal existing baseline source/local registry must be unchanged')
    check=document(selected['check'])
    need(check['status']=='passed' and check['native_lean_returncode']==0
        and check['native_invocations']==check['native_lean_invocations']==1
        and check['augmented_source']==selected['source_record']['source']
        and check['environment_manifest']==selected['local_record']['environment']
        and [{k:r[k] for k in ('path','bytes','sha256')} for r in check['compiled_artifacts']]==selected['source_record']['compiled']
        and [r['theorem'] for r in check['theorem_axiom_output']]==selected['queries']
        and all(r['report_occurrences']==2 and set(r['axioms'])<={'propext','Classical.choice','Quot.sound'}
                for r in check['theorem_axiom_output']),
        'actual unchanged baseline native/Standard2/source/environment/object evidence required')
    # GeneratedRelay intentionally permits only TypedNumericSlice itself. Its
    # reviewed guard-context parent exposes the unchanged public check_row API.
    # Forward this exact pinned baseline row through that public verifier; never
    # override an internal dispatch table or invent modern owner fields.
    return PT['PT']['qualified_module'](name,profile,selected['check'])


def import_extension(base,imports):
    need(type(imports) is list and imports==[],
         'relay has no staged imports; old convergence module cannot be admitted as a parent')
    need(base==document(BASE_PROFILE) and len(base['files'])==base['external_file_count']==20184
        and all(r['module']!='OriginalRealConvergenceV2' for r in base['source_import_modules'])
        and all(r['module']!='OriginalRealConvergenceV2' for r in base['local_checked_modules']),
        'exact unchanged baseline must have no old convergence alias')
    extended=dict(base);extended['staged_qualified_imports']=[]
    return extended,[]
